[TFMpageType('UnplannedItemRegistration', "Unplanned Item Registration")]
class TFMPageUnplannedItemRegistration extends TFMPage
{

}

Method.Source:
protected void addPageTiles()
{
    str formName;
    str navtotext;
    TFMCollectorMapAttribute    attribute = new TFMCollectorMapAttribute(classStr(TFMGetRegistrationConfiguration), this.parmId());
    TFMDocumentTypeAttribute    docTypeattr = new TFMDocumentTypeAttribute(classStr(TFMGetRegistrationConfiguration), this.parmId());


    if (docHand && ((TFMGetRegistrationConfiguration::getMethodFromSysAttribute(classIdGet(docHand),attribute) != null) || (TFMGetRegistrationConfiguration::getMethodFromSysAttribute(classIdGet(docHand),docTypeattr) != null)))
    {
        navtotext = strFmt("@TFM:Opensuptheflow1", attribute.parmContentType());
    }
    else if (docHand)
    {
        navtotext = "@TFM:Postsdirectly";
    }

    if (TFMProcessProvider::GetAllProcessesImpl().processExists(attribute.parmContentType()))
    {
        formName = formStr(TFMProcessOverview);
        navtotext = strFmt("@TFM:Opensuptheflow1", attribute.parmContentType());
    }

    super();
    this.addHtmlEntry("@TFM:Whenheaderisaccepted", navtotext,formName,resourceStr(TFMEntityCustomizations));
}
